const AGENCIA = 'Tu inmobiliaria';
const AGENTE_DEFECTO = 'Equipo comercial';
const AGENTES = {
  centro: 'Ana',
  norte: 'Luis',
  sur: 'Marta',
  este: 'Jorge',
  oeste: 'Elena'
};

const NL = String.fromCharCode(10);
const lead = $('Normalizar lead').first().json;
const inmuebles = $input.all().map(i => i.json);

function texto(v) { return String(v == null ? '' : v).trim(); }
function normal(v) {
  return texto(v).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ');
}

function num(v) {
  let s = texto(v).replace(/[^\d,.-]/g, '');
  if (!s) return 0;
  if (s.indexOf('.') >= 0 && s.indexOf(',') >= 0) {
    s = s.replace(/\./g, '').replace(',', '.');
  } else if (s.indexOf(',') >= 0) {
    const partes = s.split(',');
    s = (partes.length === 2 && partes[1].length <= 2) ? s.replace(',', '.') : s.replace(/,/g, '');
  } else {
    const p = s.split('.');
    if (p.length > 1 && p[p.length - 1].length === 3) s = s.replace(/\./g, '');
  }
  const n = Number(s);
  return isNaN(n) ? 0 : n;
}

function eur(n) {
  if (!n) return '';
  return n.toLocaleString('es-ES', { maximumFractionDigits: 0 }) + ' EUR';
}

const nombre = texto(lead.nombre) || 'sin nombre';
const email = texto(lead.email).toLowerCase();
const telefono = texto(lead.telefono);
const operacion = texto(lead.operacion);
const tipo = texto(lead.tipo);
const zona = texto(lead.zona);
const presupuesto = num(lead.presupuesto);
const habitaciones = num(lead.habitaciones);
const mensaje = texto(lead.mensaje);
const consentimiento = normal(lead.consentimiento);
const consent = consentimiento === 'si' || consentimiento === 'yes' || consentimiento === 'true' || consentimiento === 'on';

let score = 30;
if (email) score += 15;
if (telefono) score += 15;
if (presupuesto > 0) score += 10;
if (zona) score += 10;
if (mensaje.length >= 20) score += 10;
if (consent) score += 10;
score = Math.min(100, score);
const prioridad = score >= 70 ? 'Alta' : (score >= 45 ? 'Media' : 'Baja');

const z = normal(zona);
let comercial = AGENTE_DEFECTO;
for (const clave of Object.keys(AGENTES)) {
  if (z.indexOf(clave) >= 0) { comercial = AGENTES[clave]; break; }
}

const op = normal(operacion);
const quiereComprar = op.indexOf('comprar') === 0;
const quiereAlquilar = op.indexOf('alquilar') === 0;
const quiereVender = op.indexOf('vender') === 0;

const candidatos = [];
for (const p of inmuebles) {
  const estado = normal(p.Estado);
  if (estado && estado !== 'disponible') continue;
  const propOp = normal(p.Operacion);
  if (quiereComprar && propOp.indexOf('venta') < 0) continue;
  if (quiereAlquilar && propOp.indexOf('alquiler') < 0) continue;
  if (quiereVender) continue;

  const pt = normal(p.Tipo);
  const lt = normal(tipo);
  if (lt && pt && pt !== lt && pt.indexOf(lt) < 0 && lt.indexOf(pt) < 0) continue;
  const precio = num(p.Precio);
  if (presupuesto && precio && precio > presupuesto * 1.1) continue;

  let s = 0;
  let zonaOk = false;
  const pz = normal(p.Zona);
  if (z && pz) {
    if (pz.indexOf(z) >= 0 || z.indexOf(pz) >= 0) { s += 30; zonaOk = true; }
    else if (pz.split(' ').some(w => w.length > 2 && z.indexOf(w) >= 0)) { s += 15; zonaOk = true; }
  }
  if (lt && pt) s += 20;
  const hab = num(p.Habitaciones);
  if (habitaciones && hab) {
    if (hab === habitaciones) s += 15;
    else if (Math.abs(hab - habitaciones) === 1) s += 8;
  }
  if (presupuesto && precio) {
    if (precio <= presupuesto) s += 25;
    else s += 10;
  }
  if (s >= 10) candidatos.push({ p: p, score: s, precio: precio, zonaOk: zonaOk });
}

candidatos.sort((a, b) => b.score - a.score);
const top = candidatos.slice(0, 3);

function ficha(c) {
  const p = c.p;
  const ref = texto(p.ID) ? ' [' + texto(p.ID) + ']' : '';
  const detalle = [];
  if (texto(p.Zona)) detalle.push(texto(p.Zona));
  if (num(p.Habitaciones)) detalle.push(num(p.Habitaciones) + ' hab.');
  if (num(p.Superficie)) detalle.push(num(p.Superficie) + ' m2');
  if (c.precio) detalle.push(eur(c.precio));
  return '- ' + (texto(p.Titulo) || 'Inmueble') + ref + (detalle.length ? ' — ' + detalle.join(' · ') : '');
}

const listaInmuebles = top.map(ficha);
const inmueblesTexto = listaInmuebles.length ? listaInmuebles.join(NL) : 'Sin coincidencias directas en la cartera actual.';
const inmueblesFila = top.map(c => (texto(c.p.ID) || texto(c.p.Titulo)) + ' (' + c.score + ')').join(' | ');

const queBusca = quiereVender
  ? 'valorar tu inmueble' + (zona ? ' en ' + zona : '')
  : ((quiereAlquilar ? 'alquilar' : 'comprar') + (tipo ? ' un inmueble de tipo ' + tipo : ' un inmueble') + (zona ? ' en ' + zona : ''));

const intro = quiereVender
  ? 'Hemos recibido tu solicitud para valorar tu inmueble' + (zona ? ' en ' + zona : '') + '. Un comercial revisará los datos y se pondrá en contacto contigo.'
  : 'Hemos recibido tu solicitud para ' + queBusca + '.';
const seleccion = quiereVender
  ? 'Un comercial revisará la información y te propondrá una valoración sin compromiso.'
  : (listaInmuebles.length
      ? 'Estas son las opciones de nuestra cartera que mejor encajan con lo que buscas:' + NL + NL + inmueblesTexto
      : 'Un comercial revisará tu solicitud y te enviará una selección personalizada.');
const emailCuerpo = [
  'Hola ' + nombre + ':',
  '',
  intro,
  '',
  seleccion,
  '',
  'Si quieres ajustar la búsqueda (zona, presupuesto o tipo de inmueble), responde a este correo y lo tendremos en cuenta.',
  '',
  'Has recibido este correo porque has enviado una solicitud de información a ' + AGENCIA + '. Tus datos se tratan únicamente para gestionar tu solicitud. Puedes ejercer tus derechos de acceso, rectificación y supresión respondiendo a este correo.',
  '',
  'Un saludo,',
  AGENCIA
].join(NL);

const ahora = new Date();
const pad = n => String(n).padStart(2, '0');
const id = 'LEAD-' + ahora.getFullYear() + pad(ahora.getMonth() + 1) + pad(ahora.getDate()) + '-' + pad(ahora.getHours()) + pad(ahora.getMinutes()) + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
const fecha = ahora.getFullYear() + '-' + pad(ahora.getMonth() + 1) + '-' + pad(ahora.getDate()) + ' ' + pad(ahora.getHours()) + ':' + pad(ahora.getMinutes());

const tgLineas = [
  'Nuevo lead [' + prioridad + ' · ' + score + '/100]',
  '',
  'Nombre: ' + nombre,
  'Teléfono: ' + (telefono || 'no indicado'),
  'Email: ' + (email || 'no indicado'),
  'Operación: ' + (operacion || '-'),
  'Tipo: ' + (tipo || '-') + ' · Zona: ' + (zona || '-'),
  'Presupuesto: ' + (presupuesto ? eur(presupuesto) : 'no indicado'),
  'Asignado a: ' + comercial,
  'Coincidencias: ' + top.length + (top.length ? ' -> ' + top.map(c => texto(c.p.ID) || texto(c.p.Titulo)).join(', ') : ''),
  'ID: ' + id
];
if (!consent) tgLineas.push('AVISO: sin consentimiento, no se ha enviado email automático.');
const tgTexto = tgLineas.join(NL);

return [{
  json: {
    id: id,
    fecha: fecha,
    nombre: nombre,
    email: email,
    telefono: telefono,
    operacion: operacion,
    tipo: tipo,
    zona: zona,
    presupuesto: presupuesto || '',
    habitaciones: habitaciones || '',
    mensaje: mensaje,
    consentimiento: consent ? 'Sí' : 'No',
    puntuacion: score,
    prioridad: prioridad,
    comercial: comercial,
    inmuebles: inmueblesFila,
    estado: 'Nuevo',
    email_to: email,
    email_asunto: 'Tu solicitud inmobiliaria - ' + AGENCIA,
    email_cuerpo: emailCuerpo,
    tg_texto: tgTexto
  }
}];

const NL = String.fromCharCode(10);
const AHORA = new Date();
const LIMITE_HORAS = 24;

function parseFecha(v) {
  if (!v) return null;
  if (v instanceof Date) return v;
  const s = String(v).trim();
  if (!s) return null;
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) {
    const d = new Date(s.replace(' ', 'T'));
    return isNaN(d.getTime()) ? null : d;
  }
  const m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:\s+(\d{1,2}):(\d{2}))?/);
  if (m) return new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1]), Number(m[4] || 0), Number(m[5] || 0));
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

const pendientes = [];
for (const item of $input.all()) {
  const l = item.json;
  const estado = String(l.Estado || '').trim().toLowerCase();
  if (estado !== 'nuevo') continue;
  const f = parseFecha(l.Fecha);
  if (!f) continue;
  const horas = Math.round((AHORA.getTime() - f.getTime()) / 3600000);
  if (horas < LIMITE_HORAS) continue;
  pendientes.push({
    id: String(l.ID || '').trim(),
    nombre: String(l.Nombre || 'sin nombre').trim(),
    telefono: String(l.Telefono || 'sin teléfono').trim(),
    zona: String(l.Zona || '-').trim(),
    prioridad: String(l.Prioridad || '-').trim(),
    comercial: String(l.Comercial || 'sin asignar').trim(),
    horas: horas,
    fecha: f.getTime()
  });
}

if (!pendientes.length) return [];
pendientes.sort((a, b) => a.fecha - b.fecha);
const lineas = pendientes.map(l => '- ' + l.id + ' · ' + l.nombre + ' · ' + l.zona + ' · ' + l.prioridad + ' · ' + l.comercial + ' · ' + l.telefono + ' · ' + l.horas + ' h');
const texto = 'Leads sin atender (más de 24 h): ' + pendientes.length + NL + NL + lineas.join(NL) + NL + NL + 'Marca Estado = Contactado cuando lo hayas atendido.';

return [{ json: { texto: texto, total: pendientes.length } }];
